customCSS:
.t, .history { color: #545454; }
.join { color: #c3e88d; }
.part, .quit { color: #545454; }
.kick, .error { color: #f07178; }
.notice { color: #ffcb6b; }
.action { color: #c792ea; }
.mode, .nick, .topic, .server { color: #89ddff; }
.highlight { color: #eeffff; background-color: #404040; border-left: 3px solid #c792ea; padding-left: 8px; }
.reply { color: #545454; border-left: 2px solid #82aaff; padding-left: 6px; }
.oper { color: #212121; background-color: #ffcb6b; }
.reactions { color: #82aaff; background-color: #292929; }
.card { background-color: #292929; border-color: #545454; }
.card-title { color: #82aaff; }
.card-desc { color: #545454; }
.daychange { color: #545454; border-color: #292929; }
